using System.ComponentModel.DataAnnotations; using UserManagementAPI.DTOs; using Xunit;
public class ValidationTests { [Fact] public void InvalidEmail_IsRejected(){var r=new CreateUserRequest("Ali","not-an-email","User");var ctx=new ValidationContext(r);var results=new List<ValidationResult>();Assert.False(Validator.TryValidateObject(r,ctx,results,true));} [Fact] public void ValidUser_IsAccepted(){var r=new CreateUserRequest("Ali Hamza","ali@example.com","User");var ctx=new ValidationContext(r);var results=new List<ValidationResult>();Assert.True(Validator.TryValidateObject(r,ctx,results,true));} }